// Owner-local credential preparation. No code is generated by the server,
// persisted in a page, sent to Codex, or submitted to Cloudflare configuration.
const SCRIPT = String.raw`(()=>{'use strict';
const input=document.querySelector('#code'),status=document.querySelector('#status'),copy=document.querySelector('#copy'),check=document.querySelector('#check'),save=document.querySelector('#save');
let generation=0,pending=null;
const valid=()=>/^[A-Za-z0-9_-]{43}$/.test(input.value)&&/[AEIMQUYcgkosw048]$/.test(input.value);
function changed(){generation++;pending?.abort();pending=null;copy.disabled=check.disabled=save.disabled=!valid();status.textContent='코드를 보관한 뒤 Cloudflare와 Play Console에 같은 값을 입력하세요.';}
input.addEventListener('input',changed);
document.querySelector('#generate').addEventListener('click',()=>{
 try{if(!isSecureContext||!crypto?.getRandomValues)throw Error();const bytes=crypto.getRandomValues(new Uint8Array(32));input.value=btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');changed();}
 catch{status.textContent='보안 난수를 만들지 못했습니다. HTTPS 브라우저에서 다시 열어 주세요.';}
});
copy.addEventListener('click',async()=>{
 if(!valid()||document.visibilityState!=='visible')return;const current=generation,value=input.value;
 try{await navigator.clipboard.writeText(value);if(current===generation&&document.visibilityState==='visible')status.textContent='복사했습니다. 비밀번호 관리자에 먼저 저장하고 두 설정 화면에 붙여넣으세요.';}
 catch{if(current===generation)status.textContent='복사하지 못했습니다. 브라우저의 클립보드 권한을 확인하세요.';}
});
save.addEventListener('click',()=>{
 if(!valid()||document.visibilityState!=='visible')return;
 const contents='SOUL READER review access\nUsername: play-review\nPassword: '+input.value+'\n\nPrivate: keep this file on your own device. Do not upload or send it in chat.\n';
 const url=URL.createObjectURL(new Blob([contents],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');
 link.href=url;link.download='SOUL_READER_REVIEW_ACCESS_PRIVATE.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 status.textContent='코드 보관 파일 다운로드를 시작했습니다. 휴대폰의 다운로드 폴더에서 확인하고 다른 사람에게 보내지 마세요.';
});
check.addEventListener('click',async()=>{
 if(!valid()||document.visibilityState!=='visible')return;const current=generation,value=input.value,controller=new AbortController();pending?.abort();pending=controller;check.disabled=true;
 const timer=setTimeout(()=>controller.abort(),15000);status.textContent='현재 서버에 등록된 코드와 일치하는지 확인하고 있습니다.';
 try{
  const response=await fetch('/v1/review-access',{method:'POST',credentials:'omit',redirect:'error',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'play-review',accessCode:value}),signal:controller.signal});
  const reader=response.body?.getReader();if(!reader)throw Error();let length=0,parts=[];
  try{for(;;){const item=await reader.read();if(item.done)break;length+=item.value.length;if(length>1024){await reader.cancel();throw Error();}parts.push(item.value);}}finally{reader.releaseLock();}
  const bytes=new Uint8Array(length);let offset=0;for(const part of parts){bytes.set(part,offset);offset+=part.length;}const data=JSON.parse(new TextDecoder().decode(bytes));
  if(current!==generation||document.visibilityState!=='visible')return;
  status.textContent=response.status===200&&data.access==='review'&&data.sessionDurationSeconds===3600?'연결 확인 완료: 이 코드로 심사용 로그인을 할 수 있습니다. Play Console에도 같은 코드를 입력하세요.':response.status===429?'요청이 많습니다. 1분 후 다시 확인하세요.':'아직 등록되지 않았거나 코드가 다릅니다. Cloudflare의 프로덕션 비밀 값과 배포 상태를 확인하세요.';
 }catch{if(current===generation&&document.visibilityState==='visible')status.textContent='연결을 확인하지 못했습니다. 네트워크와 배포 상태를 확인한 뒤 다시 시도하세요.';}
 finally{clearTimeout(timer);if(pending===controller)pending=null;if(current===generation)check.disabled=!valid();}
});
function clear(){generation++;pending?.abort();pending=null;input.value='';copy.disabled=check.disabled=save.disabled=true;status.textContent='화면을 벗어나 코드를 지웠습니다. 보관한 코드를 붙여넣으면 다시 확인할 수 있습니다.';}
addEventListener('pagehide',clear);document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')clear();});
})();`;
const STYLE = 'body{font-family:system-ui,sans-serif;line-height:1.8;margin:0;background:#17121f;color:#f5edf6}main{max-width:720px;margin:auto;padding:28px 20px 60px}h1{font-size:1.6rem}h2{font-size:1.15rem;margin-top:30px}a{color:#f1c9e1}code{overflow-wrap:anywhere}li{margin:10px 0}input{box-sizing:border-box;width:100%;padding:14px;border-radius:8px;font-size:16px;background:#fff;color:#211629}button{min-height:44px;padding:10px 16px;border-radius:8px;margin:8px 6px 8px 0;background:#f1c9e1;color:#241428;font-size:15px}button:disabled{opacity:.45}.note{border:1px solid #70546b;padding:16px;border-radius:10px}#status{min-height:80px;overflow-wrap:anywhere}';
export const REVIEW_SETUP_CSP = "default-src 'none'; script-src 'sha256-id7LR5XbbNFwNVtLN3vCOBpqw/JZ2OKy3gMi+SRhurE='; style-src 'sha256-VQ1DSGlnKZXba+uHSFyMzOCaJpo12ggcbv0g1PZ7OaM='; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
export const REVIEW_SETUP_PAGE = `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>SOUL READER 심사용 코드 준비</title><style>${STYLE}</style></head><body><main><h1>SOUL READER 심사용 코드 준비</h1><p class="note">운영자용 준비 화면입니다. 이 페이지를 여는 것으로 앱 접근 권한이 생기지는 않습니다. 코드는 이 브라우저에서만 생성하며, Cloudflare 비밀 값과 Play Console에는 운영자가 직접 등록합니다.</p><h2>1. 코드 생성 및 보관</h2><p>아래에서 새 코드를 만들거나 비밀번호 관리자에 보관한 코드를 붙여넣으세요. 코드를 채팅이나 스크린샷으로 보내지 마세요.</p><button id="generate" type="button">새 코드 만들기</button><label for="code">심사용 코드 · 43자</label><input id="code" type="password" maxlength="43" autocomplete="off" autocapitalize="none" spellcheck="false"><button id="copy" type="button" disabled>코드 복사</button><button id="save" type="button" disabled>코드 보관 파일 저장</button><p>복사한 코드는 비밀번호 관리자에 저장하거나 ‘코드 보관 파일 저장’을 눌러 휴대폰에 보관하세요. 보관 파일에는 코드가 그대로 들어 있으므로 본인의 기기에만 두고 채팅·공개 저장소에 보내지 마세요. 탭을 바꾸거나 화면을 벗어나면 이 페이지의 입력값은 지워집니다. 이미 등록한 코드가 있다면 새로 만들지 말고 보관한 값을 사용하세요.</p><h2>2. Cloudflare에 등록</h2><ol><li>Workers 및 Pages에서 <strong>soul-reader-billing</strong>을 여세요.</li><li><strong>설정 → 런타임 변수 및 시크릿 → 변수 추가</strong>로 이동하세요.</li><li>환경은 <strong>프로덕션</strong>, 이름은 <code>PLAY_REVIEW_ACCESS_CODE</code>, 값은 복사한 코드로 입력하세요.</li><li>유형을 <strong>비밀</strong>로 설정하고 <strong>변수 추가 및 배포</strong>를 완료하세요.</li></ol><h2>3. 서버 연결 확인</h2><p>이 화면에 보관한 코드를 다시 붙여넣고 아래 버튼을 누르세요. 이때만 코드가 같은 서비스의 심사용 로그인 서버에 HTTPS로 전송됩니다. 서버 설정 자체를 바꾸는 버튼이 아닙니다.</p><button id="check" type="button" disabled>등록한 코드로 연결 확인</button><p id="status" role="status" aria-live="polite">아직 코드를 생성하거나 입력하지 않았습니다.</p><h2>4. Play Console에 입력</h2><ul><li>이름: <code>SOUL READER review access</code></li><li>사용자 이름: <code>play-review</code></li><li>비밀번호: 위에서 생성·보관한 동일한 코드</li></ul><p>로그인 세부정보는 검토용 접근 기능이 포함된 새 앱에서 실제로 확인한 뒤 저장하세요. 코드를 바꾸는 경우에는 Cloudflare와 Play Console 양쪽을 함께 갱신해야 합니다.</p><p><a href="/privacy">개인정보처리방침</a> · <a href="/delete-account">계정 삭제 요청</a></p></main><script>${SCRIPT}</script></body></html>`;
